// === Tab: Circ ===
class Circ {
	constructor(x, y, r, clr) {
		this.pos = createVector(x, y);
		this.r = r;
		this.d = r + r;
		this.vel = p5.Vector.random2D().mult(random(0.1, 0.2));
		this.clr = clr;
	}

	update() {
		this.pos.add(this.vel);
		if (this.pos.x < this.r || this.pos.x > width-this.r) this.vel.x *= -1;
		if (this.pos.y < this.r || this.pos.y > height+this.r) this.vel.y *= -1;
	}

	draw() {
		stroke(this.clr);
		circle(this.pos.x, this.pos.y, this.d);
	}

	// https://paulbourke.net/geometry/circlesphere/
	intersectingLine(other, eps = 0.00001) {
		/*
	   First calculate the distance d between the center of the circles. d = ||P1 - P0||.
	    - If d > r0 + r1 then there are no solutions, the circles are separate.
	    - If d < |r0 - r1| then there are no solutions because one circle is contained within the other.
	    - If d = 0 and r0 = r1 then the circles are coincident and there are an infinite number of solutions.
		*/

		// distance
		const dst = this.pos.dist(other.pos);

		// no intersections
		if (dst >= this.r + other.r) return null;
		if (dst <= abs(this.r - other.r)) return null;
		if (dst < eps && abs(this.r - other.r) < eps) return null;

		// calculate intersection points
		const a = (this.r**2 - other.r**2 + dst**2) / (2*dst);
		const h = Math.sqrt(this.r**2 - a**2);
		const P2 = p5.Vector.add(this.pos, p5.Vector.mult(p5.Vector.sub(other.pos, this.pos), a/dst));
		const dx = (other.pos.x - this.pos.x) * h / dst;
		const dy = (other.pos.y - this.pos.y) * h / dst;

		const x1 = P2.x+dy;
		const y1 = P2.y-dx;
		const x2 = P2.x-dy;
		const y2 = P2.y+dx;

		/*
		circle(P2.x, P2.y, 3)
		circle(x1, y1, 3)
		circle(x2, y2, 3)
		console.log(`intersection a=${a}, h=${h}`);
		*/

		const clr = lerpColor(this.clr, other.clr, 0.5);
		clr.setAlpha(16);

		const len = dist(x1, y1, x2, y2);

		return {x1, y1, x2, y2, clr, len };
	}
}

