/*
	Fire #WCCChallenge "Beautiful Burnout" //20260611 
	https://openprocessing.org/@epi/2960843
	#generativeart #creativecoding #p5js

	Dear Raph and creative coding community,

	reimplementation of the idea from "Project Somedays" 
		https://openprocessing.org/@Project-Somedays/2936167

	Used a fire colored palette and forcing that background (is random) 
	is mostly the first / black color :)

	Interactions:
   - none: time, 
   - SPACE toggle full screen, #147 not changes to whoel area drawing
   - LMB left side: pause/resume, right side: new scene

	Join the Birb's Nest Discord for friendly creative coding community
	and future challenges and contributions: https://discord.gg/S8c7qcjw2b
	WCCC-Contributions: https://openprocessing.org/curation/78544
*/

const FIRE_PAL = ["black", "red","white","yellow","darkorange","black","white"];
const NUM = 20, ITER = 25;
let circles;
let epiColors; // https://github.com/epibyte/p5-epi-colors

function setup() {
	createCanvas(windowWidth, windowHeight);
	pixelDensity(1);
	describe("intersection of lines from circle circle intersections with a fire based palette");
	stroke("deeppink");
	stroke("#FF149240");
	strokeWeight(2.5);
	noFill();

	const { EpiColors } = EpiColorsPckg;
	epiColors = new EpiColors([FIRE_PAL]);

	init();
}

function init() {
	circles = [];
	const S = max(width, height);
	for (let i = 0; i < NUM; i++) {
		const r = random(0.1, 0.2 ) * S;
		const x = random(r, width-r);
		const y = random(r, height-r);
		const clr = epiColors.palette[i % epiColors.palette.length];
		circles.push(new Circ(x, y, r, clr));
	}

	epiColors.getRandomPalette();
	if (frameCount === 0 || random()<0.5) epiColors.BG = epiColors.palette[0];
	FG = epiColors.FG;
	BG = epiColors.BG;

	blendMode(BLEND);
	background(BG);
	// blendMode(ADD);
	loop();
	// noLoop();
}

function draw() {
	// background(BG);
	blendMode(BLEND);
	// if (frameCount % 2) blendMode(ADD);

	for (let it = 0; it < ITER; it++) {	
		for (const c of circles) {
			c.update();
			// c.draw();
		}

		const lns = getIntersectionLines(circles);
		if (false) {
			for (let i = 0; i < lns.length-1; i++) {
				const ln1 = lns[i];
				for (let j = i; j < lns.length; j++) {
					const ln2 = lns[j];
					const pt = intersectionPtLineLine(ln1, ln2);
					if (pt) {
						stroke(pt.clr);
						point(pt.x, pt.y);
						// noLoop();
					}
				}
			}
		} else {
			for (const ln of lns) {
				const clr = ln.clr;
				clr.setAlpha(4);
				stroke(clr);
				line(ln.x1, ln.y1, ln.x2, ln.y2);
			}
		}
		// console.log(lns); noLoop();
	}
}

function getIntersectionLines(circles) {
	const lns = [];

	for (let i = 0; i < circles.length-1; i++) {
		const c1 = circles[i];
		for (let j = i+1; j < circles.length; j++) {
			const c2 = circles[j];
			// console.log(`i: ${i}, j: ${j}`);
			const ln = c1.intersectingLine(c2);
			if (ln) {
				lns.push(ln);
				// stroke(ln.clr);
				// point(lerp(ln.x1, ln.x2, 0.5), lerp(ln.y1, ln.y2, 0.5));
				// line(ln.x1, ln.y1, ln.x2, ln.y2);
			}
		}
	}

	return lns;
}

function mousePressed() {
	if (!mouseButton.left) return;

	if ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) > 0.5 * width) {
		init();
		return;
	}

	if (isLooping()) {
		noLoop();
	} else {
		loop();
	}
}

function keyPressed() {
	if (key != " ") return;

	if (fullscreen()) {
		fullscreen(false);
	} else {
		fullscreen(true);
		resizeCanvas(windowWidth, windowHeight); // hm, doesnt change the blank area
	}
}

function windowResized() {
	resizeCanvas(windowWidth, windowHeight);
	init();
}

function intersectionPtLineLine(ln1, ln2, eps = 0.0001) {
	const x1 = ln1.x1, y1 = ln1.y1;
	const x2 = ln1.x2, y2 = ln1.y2;
	const x3 = ln2.x1, y3 = ln2.y1;
	const x4 = ln2.x2, y4 = ln2.y2;
	const denominator = (y4-y3)*(x2-x1) - (x4-x3)*(y2-y1);
	if (abs(denominator) < eps) return null; 
	const divident = (x4-x3)*(y1-y3) - (y4-y3)*(x1-x3);

	const f = divident / denominator; // console.log(f);	
	if (f<0 || f>1) return null;

	const x = x1 + f * (x2-x1)
	const y = y1 + f * (y2-y1)
	const fLen = ln1.len/(ln1.len+ln2.len);
	const clr = lerpColor(ln1.clr, ln2.clr, fLen);

	return {x, y, clr};
}

// 1. 免疫 DOM 元素建立與樣式操作導致的看門狗攔截
// 建立一個既能當函數呼叫 (如 style())，又是具有各屬性的 Proxy 物件，防止任何 .style、.style()、.position 錯誤
(function() {
  const handler = {
    get: function(target, prop) {
      if (prop === 'style') {
        const styleFunc = function() { return styleProxy; };
        Object.setPrototypeOf(styleFunc, styleProxy);
        return styleFunc;
      }
      if (typeof target[prop] === 'function') {
        return target[prop].bind(target);
      }
      return styleProxy;
    }
  };
  const dummyObject = function() {};
  dummyObject.position = function() { return dummyObject; };
  dummyObject.style = function() { return dummyObject; };
  dummyObject.size = function() { return dummyObject; };
  dummyObject.parent = function() { return dummyObject; };
  dummyObject.id = function() { return ""; };
  dummyObject.class = function() { return dummyObject; };
  dummyObject.mousePressed = function() { return dummyObject; };
  dummyObject.mouseOver = function() { return dummyObject; };
  dummyObject.changed = function() { return dummyObject; };
  dummyObject.html = function() { return dummyObject; };
  dummyObject.value = function() { return 0; };

  const styleProxy = new Proxy(dummyObject, handler);

  if (typeof createP === 'undefined') { window.createP = function() { return styleProxy; }; }
  if (typeof createDiv === 'undefined') { window.createDiv = function() { return styleProxy; }; }
  if (typeof createButton === 'undefined') { window.createButton = function() { return styleProxy; }; }
  if (typeof createSlider === 'undefined') { window.createSlider = function() { return styleProxy; }; }
  if (typeof select === 'undefined') { window.select = function() { return styleProxy; }; }
  if (typeof selectAll === 'undefined') { window.selectAll = function() { return [styleProxy]; }; }
})();

// 1.2 免疫 HTML 屬性與 Element.prototype.style 崩潰 (確保 style 與 checked 既可以當物件又可以當函數呼叫)
try {
  if (typeof Element !== 'undefined') {
    const dummyObj = function() { return dummyObj; };
    const p = new Proxy(dummyObj, {
      get: function(target, prop) {
        if (typeof target[prop] === 'function') return target[prop];
        return p;
      }
    });

    // 用屬性定義防止被覆寫
    Object.defineProperty(Element.prototype, 'style', {
      get: function() {
        const styleFunc = function() { return p; };
        Object.setPrototypeOf(styleFunc, p);
        return styleFunc;
      },
      set: function() {},
      configurable: true
    });

    Object.defineProperty(Element.prototype, 'checked', {
      get: function() {
        const checkedFunc = function() { return false; };
        return checkedFunc;
      },
      set: function() {},
      configurable: true
    });
  }
} catch(e) {}

// 1.3 免疫 HTMLInputElement.size = 0 或非法負數導致的瀏覽器拋錯
try {
  if (typeof HTMLInputElement !== 'undefined') {
    const desc = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'size');
    if (desc && desc.set) {
      const originalSet = desc.set;
      Object.defineProperty(HTMLInputElement.prototype, 'size', {
        set: function(val) {
          if (val <= 0) val = 20; // 設為預設合規大小
          originalSet.call(this, val);
        },
        configurable: true
      });
    }
  }
} catch(e) {}

// 1.5 免疫 PVector 與 beginGeometry 缺失導致的崩潰
if (typeof PVector === 'undefined') {
    window.PVector = class PVector {
        constructor(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
        static dist(v1, v2) {
            return Math.sqrt((v1.x - v2.x) ** 2 + (v1.y - v2.y) ** 2 + (v1.z - v2.z) ** 2);
        }
        set(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
    };
}
if (typeof beginGeometry === 'undefined') { window.beginGeometry = function() {}; }
if (typeof endGeometry === 'undefined') { window.endGeometry = function() { return { draw: function() {} }; }; }

